"use client";

import { lazy, Suspense, useSyncExternalStore } from "react";

const emptySubscribe = () => () => undefined;

const Scene = lazy(() => import("./scene"));

/** Wire a route to this file after install. WebGL loads only in the browser. */
export default function ChatCardPage() {
  const mounted = useSyncExternalStore(
    emptySubscribe,
    () => true,
    () => false
  );
  if (!mounted) {
    return <div className="h-dvh w-full bg-background" />;
  }
  return (
    <Suspense fallback={<div className="h-dvh w-full bg-background" />}>
      <Scene />
    </Suspense>
  );
}

"use client";

import { Canvas, useFrame, useThree } from "@react-three/fiber";
import { IfInSessionMode, useXR, XR } from "@react-three/xr";
import { useCallback, useRef, useState } from "react";
import type { Group } from "three";
import {
  type CardSize,
  cardMeters,
  placeAtGaze,
  WorldCard,
  WorldThemeProvider,
} from "@/components/ui/world-card";
import { ChatCardBody } from "./chat-body";
import { ExperienceHud } from "./hud";
import { ORB_RADIUS, SpeakingOrb } from "./speaking-orb";
import { xrStore } from "./xr-store";

const CHAT_CARD = {
  w: 340,
  h: 520,
  minW: 280,
  minH: 400,
  maxW: 800,
  maxH: 720,
};
const ORB_LIFT = 0.08;
const DESKTOP_POS: [number, number, number] = [0, 1.52, -0.35];

function appearanceFromDom(): "light" | "dark" {
  if (typeof document === "undefined") {
    return "dark";
  }
  return document.documentElement.classList.contains("dark") ? "dark" : "light";
}

function Studio({ appearance }: { appearance: "light" | "dark" }) {
  const major = appearance === "dark" ? 0x4b5158 : 0xc9cdd3;
  const minor = appearance === "dark" ? 0x2c3036 : 0xe2e4e8;
  const floor = appearance === "dark" ? "#1a1d21" : "#eeeff1";
  return (
    <>
      <color attach="background" args={[floor]} />
      <mesh position={[0, 0, 0]} rotation={[-Math.PI / 2, 0, 0]}>
        <planeGeometry args={[12, 12]} />
        <meshStandardMaterial color={floor} />
      </mesh>
      <gridHelper args={[8, 32, major, minor]} />
    </>
  );
}

function ChatDock() {
  const session = useXR((s) => s.session);
  const camera = useThree((s) => s.camera);
  const [open, setOpen] = useState(true);
  const [size, setSize] = useState<CardSize>({
    w: CHAT_CARD.w,
    h: CHAT_CARD.h,
  });
  const meters = cardMeters(size);
  const orbTop = meters.h / 2 + ORB_LIFT;
  const orbLift = useRef(0);
  const orbSlot = useRef<Group>(null);
  const dragging = useRef(false);
  const anchor = useRef<Group>(null);
  const placedSession = useRef(false);
  const placedDesktop = useRef(false);

  const bringHere = useCallback(() => {
    const a = anchor.current;
    if (!a) {
      return;
    }
    placeAtGaze(a, camera, {
      distance: 0.55,
      drop: 0.25,
      side: 0.18,
      face: true,
    });
    placedSession.current = true;
  }, [camera]);

  useFrame((_, dt) => {
    const a = anchor.current;
    if (!a) {
      return;
    }
    if (session) {
      placedDesktop.current = false;
      if (!placedSession.current) {
        bringHere();
      }
    } else if (!placedDesktop.current) {
      a.position.set(...DESKTOP_POS);
      a.rotation.set(0, 0, 0);
      placedDesktop.current = true;
      placedSession.current = false;
    }
    const orbGoal = open ? orbTop : 0;
    orbLift.current += (orbGoal - orbLift.current) * Math.min(1, 10 * dt);
    if (orbSlot.current) {
      orbSlot.current.position.y = orbLift.current;
    }
  });

  const toggleCard = () => {
    if (dragging.current) {
      return;
    }
    setOpen((value) => !value);
  };

  return (
    <WorldCard
      ref={anchor}
      limits={CHAT_CARD}
      movable
      onDragEnd={() => {
        dragging.current = false;
      }}
      onDragStart={() => {
        dragging.current = true;
      }}
      handle={open}
      onSizeChange={setSize}
      radius={ORB_RADIUS}
      resizable={open}
      shape={open ? "card" : "orb"}
      size={size}
    >
      <group ref={orbSlot}>
        <SpeakingOrb onClick={toggleCard} />
      </group>
      {open ? <ChatCardBody height={size.h} width={size.w} /> : null}
    </WorldCard>
  );
}

export default function ChatCardScene() {
  const appearance = appearanceFromDom();

  return (
    <div className="relative h-dvh w-full overflow-hidden bg-background">
      <ExperienceHud />
      <Canvas
        camera={{
          fov: 70,
          near: 0.01,
          far: 50,
          position: [0, 1.6, 0.15],
          rotation: [0, 0, 0],
        }}
        gl={{ antialias: true, alpha: true }}
        style={{ position: "absolute", inset: 0, touchAction: "none" }}
      >
        <XR store={xrStore}>
          <hemisphereLight args={[0xffffff, 0xb8bcc2, 0.95]} />
          <directionalLight intensity={1.35} position={[0.55, 1.6, 0.45]} />
          <WorldThemeProvider appearance={appearance}>
            <IfInSessionMode deny="immersive-ar">
              <Studio appearance={appearance} />
            </IfInSessionMode>
            <ChatDock />
          </WorldThemeProvider>
        </XR>
      </Canvas>
    </div>
  );
}

import { createXRStore } from "@react-three/xr";

const CURSOR_OFFSET = 0.001;

const rightRay = {
  minDistance: 0.02,
  rayModel: { opacity: 0.55, color: "#e4e4e7" },
  cursorModel: {
    opacity: 0.9,
    size: 0.006,
    color: "#2563eb",
    cursorOffset: CURSOR_OFFSET,
  },
};

const hands = {
  model: true,
  grabPointer: true,
  touchPointer: true,
  rayPointer: {
    minDistance: 0.02,
    rayModel: { opacity: 0.4, color: "#e4e4e7", maxLength: 1.2 },
    cursorModel: {
      opacity: 0.85,
      size: 0.005,
      color: "#2563eb",
      cursorOffset: CURSOR_OFFSET,
    },
  },
} as const;

export const xrStore = createXRStore({
  foveation: 0.5,
  offerSession: false,
  bounded: true,
  hitTest: false,
  domOverlay: false,
  anchors: false,
  meshDetection: false,
  planeDetection: false,
  depthSensing: false,
  bodyTracking: false,
  handTracking: true,
});

function applyARInput() {
  xrStore.setController(
    { model: false, rayPointer: false, grabPointer: false },
    "left"
  );
  xrStore.setController(
    { model: false, rayPointer: rightRay, grabPointer: true },
    "right"
  );
  xrStore.setHand(hands, "left");
  xrStore.setHand(hands, "right");
}

function applyVRInput() {
  xrStore.setController(
    { model: true, rayPointer: false, grabPointer: true },
    "left"
  );
  xrStore.setController(
    { model: true, rayPointer: rightRay, grabPointer: true },
    "right"
  );
  xrStore.setHand(hands, "left");
  xrStore.setHand(hands, "right");
}

export function enterAR() {
  applyARInput();
  return xrStore.enterAR();
}

export function enterVR() {
  applyVRInput();
  return xrStore.enterVR();
}

"use client";

import { Container, Text } from "@react-three/uikit";
import { useState } from "react";
import { VrChatInput } from "@/components/ui/vr-chat-input";
import { asciiSafe, VrMarkdown } from "@/components/ui/vr-markdown";
import { VrReasoning } from "@/components/ui/vr-reasoning";
import { VrTool } from "@/components/ui/vr-tool";
import { VrWorked } from "@/components/ui/vr-worked";
import { splitWorkedParts } from "@/components/ui/worked";
import { useWorldTheme } from "@/components/ui/world-card";
import {
  type CardMessage,
  type CardPart,
  INITIAL_MESSAGES,
} from "./mock-messages";

function VrPart({ part }: { part: CardPart }) {
  if (part.type === "text" && part.text) {
    return <VrMarkdown markdown={part.text} />;
  }
  if (part.type === "reasoning" && part.text) {
    return <VrReasoning text={part.text} />;
  }
  if (part.type.startsWith("tool-") || part.type === "dynamic-tool") {
    return (
      <VrTool
        input={part.input}
        output={part.output}
        toolName={part.toolName ?? part.type}
      />
    );
  }
  return null;
}

function VrAssistantParts({ message }: { message: CardMessage }) {
  return (
    <Container flexDirection="column" flexShrink={0} gap={8} width="100%">
      {splitWorkedParts(message.parts).map((segment) => {
        if (segment.kind === "worked") {
          const start = segment.items[0]?.index ?? 0;
          return (
            <VrWorked key={`w-${start}`}>
              {segment.items.map((item) => (
                <VrPart key={item.index} part={item.part} />
              ))}
            </VrWorked>
          );
        }
        return <VrPart key={segment.item.index} part={segment.item.part} />;
      })}
    </Container>
  );
}

function XrMessageRow({ message }: { message: CardMessage }) {
  const mine = message.role === "user";
  const theme = useWorldTheme();
  const text = message.parts
    .filter((part) => part.type === "text")
    .map((part) => part.text ?? "")
    .join("\n");
  if (mine && !text) {
    return null;
  }
  return (
    <Container
      alignItems={mine ? "flex-end" : "flex-start"}
      flexDirection="column"
      flexShrink={0}
      width="100%"
    >
      {mine ? (
        <Container
          alignSelf="flex-end"
          backgroundColor={theme.bubble}
          borderRadius={10}
          flexShrink={0}
          maxWidth="80%"
          padding={8}
          width="auto"
        >
          <Text color={theme.text} fontSize={13}>
            {asciiSafe(text)}
          </Text>
        </Container>
      ) : (
        <Container flexShrink={0} maxWidth="100%" width="100%">
          <VrAssistantParts message={message} />
        </Container>
      )}
    </Container>
  );
}

export function ChatCardBody({
  width,
  height,
}: {
  width: number;
  height: number;
}) {
  const theme = useWorldTheme();
  const [messages, setMessages] = useState(INITIAL_MESSAGES);

  const send = (text: string) => {
    const id = `m-${messages.length + 1}`;
    setMessages((current) => [
      ...current,
      { id: `${id}-u`, parts: [{ text, type: "text" }], role: "user" },
      {
        id: `${id}-a`,
        parts: [
          {
            text: "Mocked reply. Point the transport at your API when you have one.",
            type: "text",
          },
        ],
        role: "assistant",
      },
    ]);
  };

  return (
    <Container
      backgroundColor={theme.card}
      borderRadius={12}
      flexDirection="column"
      gap={6}
      height={height}
      padding={8}
      pixelSize={0.001}
      pointerEvents="auto"
      width={width}
    >
      <Text color={theme.text} fontSize={14}>
        Assistant
      </Text>
      <Container
        backgroundColor={theme.border}
        flexShrink={0}
        height={1}
        width="100%"
      />
      <Container
        flexDirection="column"
        flexGrow={1}
        gap={6}
        minHeight={0}
        overflow="scroll"
        width="100%"
      >
        {messages.map((message) => (
          <XrMessageRow key={message.id} message={message} />
        ))}
      </Container>
      <Container
        backgroundColor={theme.border}
        flexShrink={0}
        height={1}
        width="100%"
      />
      <VrChatInput onSubmit={send} />
    </Container>
  );
}

"use client";

import { useFrame } from "@react-three/fiber";
import { useRef } from "react";
import type { Mesh } from "three";
import { useWorldTheme } from "@/components/ui/world-card";

export const ORB_RADIUS = 0.04;

export function SpeakingOrb({ onClick }: { onClick: () => void }) {
  const mesh = useRef<Mesh>(null);
  const theme = useWorldTheme();

  useFrame((state) => {
    const m = mesh.current;
    if (!m) {
      return;
    }
    const t = state.clock.elapsedTime;
    const s = 1 + Math.sin(t * 2.2) * 0.04;
    m.scale.setScalar(s);
  });

  return (
    <mesh ref={mesh} name="speaking-orb" onClick={onClick}>
      <icosahedronGeometry args={[ORB_RADIUS, 2]} />
      <meshStandardMaterial
        color={theme.card}
        emissive={theme.hover}
        emissiveIntensity={0.45}
        metalness={0.2}
        roughness={0.35}
      />
    </mesh>
  );
}

export type CardPart = {
  type: string;
  text?: string;
  toolName?: string;
  input?: unknown;
  output?: unknown;
};

export type CardMessage = {
  id: string;
  role: "user" | "assistant";
  parts: CardPart[];
};

export const INITIAL_MESSAGES: CardMessage[] = [
  {
    id: "u1",
    role: "user",
    parts: [{ type: "text", text: "What am I looking at?" }],
  },
  {
    id: "a1",
    role: "assistant",
    parts: [
      {
        type: "reasoning",
        text: "The wearer is in a VR session. I will describe the card in the scene, not a 2D page.",
      },
      {
        type: "text",
        text: "You are looking at a VR chat card. Drag the handle to move it. Pinch a corner to resize. Enter VR or AR to place it at your gaze.",
      },
    ],
  },
  {
    id: "u2",
    role: "user",
    parts: [{ type: "text", text: "Make the hole 8mm." }],
  },
  {
    id: "a2",
    role: "assistant",
    parts: [
      {
        type: "tool-cad_edit",
        toolName: "cad_edit",
        input: { feature: "hole", diameter_mm: 8 },
        output: { ok: true, diameter_mm: 8 },
      },
      {
        type: "text",
        text: "Updated the hole to 8 mm. The card stays in world space while the model rebuilds.",
      },
    ],
  },
];

"use client";

import { useEffect, useState } from "react";
import { enterAR, enterVR } from "./xr-store";

type XrSupport = { ar: boolean; vr: boolean; ready: boolean };

function SessionButton({
  enabled,
  label,
  onEnter,
}: {
  enabled: boolean;
  label: string;
  onEnter: () => void;
}) {
  return (
    <button
      className="h-9 rounded-lg px-3 text-sm disabled:cursor-not-allowed disabled:opacity-40"
      disabled={!enabled}
      onClick={() => {
        if (enabled) {
          onEnter();
        }
      }}
      title={enabled ? label : "Needs a headset (Quest Browser)"}
      type="button"
    >
      {label}
    </button>
  );
}

export function ExperienceHud() {
  const [support, setSupport] = useState<XrSupport>({
    ar: false,
    vr: false,
    ready: false,
  });

  useEffect(() => {
    const xr = navigator.xr;
    if (!xr) {
      setSupport({ ar: false, vr: false, ready: true });
      return;
    }
    let cancelled = false;
    Promise.all([
      xr.isSessionSupported("immersive-ar").catch(() => false),
      xr.isSessionSupported("immersive-vr").catch(() => false),
    ]).then(([ar, vr]) => {
      if (!cancelled) {
        setSupport({ ar, vr, ready: true });
      }
    });
    return () => {
      cancelled = true;
    };
  }, []);

  const xrReady = support.ready && (support.ar || support.vr);

  return (
    <div className="pointer-events-auto absolute top-4 right-4 z-10 flex max-w-[min(100%-2rem,28rem)] flex-col items-end gap-2">
      <p className="rounded-lg border border-border bg-card/95 px-3 py-2 text-muted-foreground text-xs shadow-lg">
        Drag the handle to move. Corners and edges resize.
        {support.ready && !xrReady
          ? " Enter VR/AR needs a headset (Quest Browser)."
          : null}
      </p>
      <div className="flex flex-wrap justify-end gap-1 rounded-xl border border-border bg-card/95 p-1 shadow-lg">
        <SessionButton
          enabled={support.vr}
          label="Enter VR"
          onEnter={() => {
            enterVR();
          }}
        />
        <SessionButton
          enabled={support.ar}
          label="Enter AR"
          onEnter={() => {
            enterAR();
          }}
        />
      </div>
    </div>
  );
}
